import os
import json
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _field_content(field: Any) -> Any:
    if field is None:
        return None
    for attr in ("content", "value", "value_string", "value_number", "value_date", "value_currency", "value_address"):
        if hasattr(field, attr):
            v = getattr(field, attr)
            if v is not None:
                return v
    return field


def _field_confidence(field: Any) -> Optional[float]:
    if field is None:
        return None
    conf = getattr(field, "confidence", None)
    try:
        return float(conf) if conf is not None else None
    except (TypeError, ValueError):
        return None


def _field_to_python(field: Any) -> Any:
    if field is None:
        return None
    if hasattr(field, "value_type") and hasattr(field, "value"):
        value = getattr(field, "value", None)
        if value is None:
            return None
        if field.value_type == "list":
            return [_field_to_python(item) for item in value]
        if field.value_type == "dictionary":
            return {k: _field_to_python(v) for k, v in value.items()}
        return _field_content(field)
    if isinstance(field, dict):
        return field
    return _field_content(field)


def extract_and_validate_document(
    document_path: str,
    required_fields: Optional[List[str]] = None,
    confidence_threshold: float = 0.8,
    model_id: str = "prebuilt-invoice",
) -> Dict[str, Any]:
    if required_fields is None:
        required_fields = [
            "InvoiceId",
            "InvoiceDate",
            "VendorName",
            "CustomerName",
            "InvoiceTotal",
        ]

    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id=model_id,
            analyze_request=f,
            content_type="application/octet-stream",
        )

    result = poller.result()

    documents = getattr(result, "documents", None) or []
    first_doc = documents[0] if documents else None
    fields = getattr(first_doc, "fields", None) if first_doc is not None else None
    fields = fields or {}

    extracted: Dict[str, Any] = {}
    field_confidences: Dict[str, Optional[float]] = {}
    validation_errors: List[str] = []

    for field_name in required_fields:
        field_obj = fields.get(field_name) if hasattr(fields, "get") else None
        value = _field_to_python(field_obj)
        confidence = _field_confidence(field_obj)

        extracted[field_name] = value
        field_confidences[field_name] = confidence

        if value is None or (isinstance(value, str) and not value.strip()):
            validation_errors.append(f"Missing required field: {field_name}")
        if confidence is None:
            validation_errors.append(f"Missing confidence score for field: {field_name}")
        elif confidence < confidence_threshold:
            validation_errors.append(
                f"Low confidence for field {field_name}: {confidence:.3f} < {confidence_threshold:.3f}"
            )

    return {
        "valid": len(validation_errors) == 0,
        "required_fields": required_fields,
        "confidence_threshold": confidence_threshold,
        "extracted_fields": extracted,
        "field_confidences": field_confidences,
        "validation_errors": validation_errors,
        "raw": result.to_dict() if hasattr(result, "to_dict") else result,
    }
